import{_ as t,P as n,I as l,g as r,j as a,l as i}from"./chunks/framework.CbuNJfvM.js";const u=JSON.parse('{"title":"object oriented programming","description":"","frontmatter":{},"headers":[],"relativePath":"object-oriented-programming.md","filePath":"object-oriented-programming.md"}'),o={name:"object-oriented-programming.md"};function h(c,e,d,p,k,g){const s=n("GhulExample");return l(),r("div",null,[e[0]||(e[0]=a('<h1 id="object-oriented-programming" tabindex="-1">object oriented programming <a class="header-anchor" href="#object-oriented-programming" aria-label="Permalink to &quot;object oriented programming&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">runnable examples</p><p>The <a href="https://github.com/degory/ghul-examples/tree/main/examples/object-oriented" target="_blank" rel="noreferrer">ghul-examples repository</a> has fuller, runnable object-oriented examples. Open it in a GitHub Codespace or a dev container to build and run them.</p></div><p>ghūl is a class-based object-oriented language. Classes and structs hold state and behaviour, traits describe shared behaviour, and a value can be used at the type of any ancestor class or trait it satisfies. This page ties those pieces together; <a href="/definitions.html#types">definitions</a> has the syntax for each in isolation.</p><h2 id="classes-and-objects" tabindex="-1">classes and objects <a class="header-anchor" href="#classes-and-objects" aria-label="Permalink to &quot;classes and objects&quot;">​</a></h2><p>A <a href="/definitions.html#classes">class</a> defines a reference type: fields and properties for its state, methods for its behaviour, and one or more <code class="ghul-inline"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">init</span></code> constructors. An object is an instance of a class, created by calling the class like a function, as in <code class="ghul-inline"><span style="--shiki-light:#267F99;--shiki-dark:#4EC9B0;">POINT</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">(</span><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;">3</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">, </span><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;">4</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">)</span></code>. <code class="ghul-inline"><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;">self</span></code> refers to the current instance inside a method. A class with no declared superclass extends <code class="ghul-inline"><span style="--shiki-light:#267F99;--shiki-dark:#4EC9B0;">object</span></code>, and objects compare by reference identity unless a class overrides equality.</p><h2 id="encapsulation" tabindex="-1">encapsulation <a class="header-anchor" href="#encapsulation" aria-label="Permalink to &quot;encapsulation&quot;">​</a></h2><p>There are no <code class="ghul-inline"><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;">public</span></code> or <code class="ghul-inline"><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;">private</span></code> keywords. A leading underscore on a name marks it non-public, and the compiler enforces that for methods and properties: <code class="ghul-inline"><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;">_</span><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">balance</span></code> is reachable only within its own type and subclasses, while <code class="ghul-inline"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">balance</span></code> is public to read. A property is public to read but assignable only within its defining type, so state stays behind the methods that maintain it.</p><h2 id="inheritance" tabindex="-1">inheritance <a class="header-anchor" href="#inheritance" aria-label="Permalink to &quot;inheritance&quot;">​</a></h2><p>A class extends at most one superclass, named after a colon in the header, and inherits its members. A constructor runs the superclass constructor with <code class="ghul-inline"><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;">super</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">.</span><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">init</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">(...)</span></code>, and a method replaces an inherited one by declaring it again. A call to that method dispatches on the object&#39;s runtime type, so a method inherited from the superclass reaches the override:</p>',9)),i(s,{name:"object-oriented-programming-2"}),e[1]||(e[1]=a('<p>Calling <code class="ghul-inline"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">describe</span></code> through the <code class="ghul-inline"><span style="--shiki-light:#267F99;--shiki-dark:#4EC9B0;">Animal</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">[]</span></code> is polymorphism: the static type is <code class="ghul-inline"><span style="--shiki-light:#267F99;--shiki-dark:#4EC9B0;">Animal</span></code>, the behaviour is each subclass&#39;s overriding <code class="ghul-inline"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">speak</span></code>.</p><h2 id="abstract-and-closed-classes" tabindex="-1">abstract and closed classes <a class="header-anchor" href="#abstract-and-closed-classes" aria-label="Permalink to &quot;abstract and closed classes&quot;">​</a></h2><p><code class="ghul-inline"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">speak</span></code> above has no body. A class with a body-less instance method is implicitly abstract: it names a method the class can&#39;t perform on its own, so constructing the class directly is rejected and only subclasses that supply the method can exist. Marking a class <code class="ghul-inline"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">abstract</span></code> has the same effect without a body-less method.</p><p>By default a class is closed to subclassing outside its own assembly; the postfix <code class="ghul-inline"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">open</span></code> modifier opts in to cross-assembly subclassing. Closing the hierarchy lets the compiler narrow on the <code class="ghul-inline"><span style="--shiki-light:#AF00DB;--shiki-dark:#C586C0;">else</span></code> edge of an <code class="ghul-inline"><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;">isa</span></code> test, and an <code class="ghul-inline"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">abstract</span></code> root can narrow to a single remaining subclass (see <a href="/control-flow.html#type-narrowing">type narrowing</a>).</p><h2 id="traits" tabindex="-1">traits <a class="header-anchor" href="#traits" aria-label="Permalink to &quot;traits&quot;">​</a></h2><p>A <a href="/definitions.html#traits">trait</a> is ghūl&#39;s interface: a set of members a type promises to provide. A class, struct, or union implements a trait by naming it in the header, and the value can then be used at the trait&#39;s type wherever the trait is expected. A class extends one superclass but implements any number of traits.</p><p>A trait member can provide a default body, which an implementing type inherits and overrides only to change, reaching the original with <code class="ghul-inline"><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;">super</span></code>. Traits combine with generics: a generic trait like <code class="ghul-inline"><span style="--shiki-light:#267F99;--shiki-dark:#4EC9B0;">Operation</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">[</span><span style="--shiki-light:#267F99;--shiki-dark:#4EC9B0;">T</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">]</span></code> gives a whole family of implementations one shared shape.</p><h2 id="narrowing" tabindex="-1">narrowing <a class="header-anchor" href="#narrowing" aria-label="Permalink to &quot;narrowing&quot;">​</a></h2><p>Discovering an object&#39;s concrete type at runtime uses <code class="ghul-inline"><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;">isa</span></code> or <code class="ghul-inline"><span style="--shiki-light:#AF00DB;--shiki-dark:#C586C0;">if</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> let</span></code>, which test the type and narrow the value to it inside the matching branch, and a <code class="ghul-inline"><span style="--shiki-light:#AF00DB;--shiki-dark:#C586C0;">case</span></code> over a closed hierarchy is checked for exhaustiveness. The <a href="/control-flow.html#type-narrowing">control flow</a> chapter covers narrowing in full.</p><h2 id="a-worked-example" tabindex="-1">a worked example <a class="header-anchor" href="#a-worked-example" aria-label="Permalink to &quot;a worked example&quot;">​</a></h2>',10)),i(s,{name:"object-oriented-programming-1"})])}const b=t(o,[["render",h]]);export{u as __pageData,b as default};
